package com.codegym.controller;
import com.codegym.model.Product; import com.codegym.service.*; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.IOException;
@WebServlet(name="ProductServlet",urlPatterns="/products") public class ProductServlet extends HttpServlet {private final ProductService service=new ProductServiceImpl(); private void f(HttpServletRequest r,HttpServletResponse s,String p)throws ServletException,IOException{r.getRequestDispatcher(p).forward(r,s);} private int id(HttpServletRequest r){return Integer.parseInt(r.getParameter("id"));} protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{String a=r.getParameter("action");try{if(a==null||a.isBlank()||"search".equals(a)){r.setAttribute("products",service.searchByName(r.getParameter("keyword")));r.setAttribute("keyword",r.getParameter("keyword"));f(r,s,"/product/list.jsp");}else if("create".equals(a))f(r,s,"/product/create.jsp");else{Product p=service.findById(id(r));if(p==null){f(r,s,"/error-404.jsp");return;}r.setAttribute("product",p);f(r,s,"/product/"+("view".equals(a)?"view":a)+".jsp");}}catch(NumberFormatException e){f(r,s,"/error-404.jsp");}} protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{r.setCharacterEncoding("UTF-8");try{String a=r.getParameter("action");if("create".equals(a)){int n=service.findAll().stream().mapToInt(Product::getId).max().orElse(0)+1;service.save(product(r,n));}else if("edit".equals(a)){int n=id(r);if(service.findById(n)==null){f(r,s,"/error-404.jsp");return;}service.update(n,product(r,n));}else if("delete".equals(a)){if(service.findById(id(r))==null){f(r,s,"/error-404.jsp");return;}service.remove(id(r));}s.sendRedirect(r.getContextPath()+"/products");}catch(NumberFormatException e){f(r,s,"/error-404.jsp");}} private Product product(HttpServletRequest r,int id){return new Product(id,r.getParameter("name"),Double.parseDouble(r.getParameter("price")),r.getParameter("description"),r.getParameter("manufacturer"));}}
